// Validate JSON output structure
const item = $input.item.json;
let parsed = {};
try {
  parsed = typeof item.text === 'string' ? JSON.parse(item.text) : item;
} catch (e) {
  parsed = item;
}

return {
  sender_name: parsed.sender_name || null,
  phone: parsed.phone || null,
  language: parsed.language || 'english',
  category: parsed.category || 'other',
  programme_interest: parsed.programme_interest || 'unknown',
  intent: parsed.intent || 'General inquiry',
  priority: parsed.priority || 'medium',
  sentiment: parsed.sentiment || 'neutral',
  confidence: typeof parsed.confidence === 'number' ? parsed.confidence : 0.9,
  key_details: Array.isArray(parsed.key_details) ? parsed.key_details : [],
  requested_follow_up: parsed.requested_follow_up || null,
  requires_human_review: Boolean(parsed.requires_human_review),
  review_reason: parsed.review_reason || null,
  suggested_reply: parsed.suggested_reply || 'Thank you for reaching out to BIAI. Our team will get back to you shortly.',
  processed_at: new Date().toISOString()
};
